const CACHE='tarif-market-v47';
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(['./','./index.html','./app.css','./catalog.js','./app.js','./oyun.html','./oyun.css','./oyun.js','./teslimat.html','./teslimat.css','./teslimat.js','./three.min.js','./gltf-loader.js','./gercekci-motor-data.js','./van-data.js','./tree-data.js','./kedi-data.js','./kus-data.js','./rider-data.js','./sedan-data.js','./polis-data.js','./apartman-data.js','./assets/surus/motor-kokpit.png','./assets/surus/araba-kokpit.png','./assets/surus/korna-eli.png','./assets/surus/araba-eller-eldivensiz.png','./assets/surus/araba-korna-eli.png','./assets/surus/motor-eller.png','./terminal-data.js','./ucak-data.js','./guvenlik-data.js','./surus-textures.js','./kaynaklar.html','./assets/surus/asphalt.jpg','./assets/surus/duvar.jpg','./assets/surus/gokyuzu.jpg','./manifest.webmanifest','./assets/kelek.jpg','./assets/salep.jpg','./assets/erikli-su.jpg','./assets/app-icon-192.png','./assets/app-icon-512.png']))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('tarif-market-')&&key!==CACHE).map(key=>caches.delete(key))))));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(cached=>cached||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});
